185	func newFactsReclassifyCommand(opts Options) *cobra.Command {
186		var (
187			force   bool
188			jsonOut bool
189		)
190		cmd := &cobra.Command{
191			Hidden: true,
192			Use:    "reclassify",
193			Short:  "Backfill the deterministic KIND onto memories missing one (no agent)",
194			Args:   cobra.NoArgs,
195			RunE: func(cmd *cobra.Command, args []string) error {
196				_, brainDir, _, err := resolveFactsTarget(cmd.Context(), opts, agentSurfaceTarget(opts, nil), "")
197				if err != nil {
198					return err
199				}
200				return runFactsReclassify(cmd, opts, brainDir, force, jsonOut)
201			},
202		}
203		cmd.Flags().BoolVar(&force, "force", false, "Recompute every memory's kind (default: only fill memories missing a valid kind)")
204		cmd.Flags().BoolVar(&jsonOut, "json", false, "Emit the reclassify summary as JSON")
205		return cmd
