299		cmd.Flags().StringVar(&gen.model, "model", "", "Override the agent model (pairs with --effort for a cheap run)")
300		cmd.Flags().StringVar(&gen.effort, "effort", "", "Override the reasoning effort for codex/claude-code")
301		cmd.Flags().IntVar(&gen.budget, "budget", 0, "Max agent summary calls this run (0 = unlimited)")
302		cmd.Flags().IntVar(&gen.minFacts, "min-memories", 2, "Skip nodes whose subtree has fewer memories than this")
303		cmd.Flags().BoolVar(&gen.force, "force", false, "Re-summarize every node, ignoring unchanged fingerprints")
304		cmd.Flags().BoolVar(&jsonOut, "json", false, "Emit the outline summary as JSON")
