283				outline, regenerated, err := generateFactOutline(cmd.Context(), repoDir, brainDir, facts, resolved, now)
284				if err != nil {
285					return err
286				}
287				if err := writeFactOutline(brainDir, outline); err != nil {
288					return err
289				}
290				if jsonOut {
291					return cmdutil.WriteJSON(cmd, map[string]any{"nodes": len(outline.Nodes), "regenerated": regenerated})
292				}
293				fmt.Fprintf(cmd.OutOrStdout(), "outline: %d node(s), %d summary(ies) regenerated\n", len(outline.Nodes), regenerated)
294				return nil
295			},
296		}
297		cmd.Flags().StringVar(&gen.agent, "agent", "auto", "Agent for summaries: auto, codex, claude-code, command, or none")
298		cmd.Flags().StringArrayVar(&gen.agentCommand, "agent-command", nil, "Agent command argv for --agent command")
299		cmd.Flags().StringVar(&gen.model, "model", "", "Override the agent model (pairs with --effort for a cheap run)")
300		cmd.Flags().StringVar(&gen.effort, "effort", "", "Override the reasoning effort for codex/claude-code")
301		cmd.Flags().IntVar(&gen.budget, "budget", 0, "Max agent summary calls this run (0 = unlimited)")
302		cmd.Flags().IntVar(&gen.minFacts, "min-memories", 2, "Skip nodes whose subtree has fewer memories than this")
303		cmd.Flags().BoolVar(&gen.force, "force", false, "Re-summarize every node, ignoring unchanged fingerprints")
304		cmd.Flags().BoolVar(&jsonOut, "json", false, "Emit the outline summary as JSON")
305		// --min-facts predates the facts→memories rename; keep it working.
306		legacyFlagAlias(cmd.Flags(), "min-facts", "min-memories")
307		return cmd
308	}
309	
310	func newFactsMapCommand(opts Options) *cobra.Command {
311		var (
312			path    string
313			depth   int
314			jsonOut bool
315		)
316		cmd := &cobra.Command{
317			Use:   "map",
318			Short: "Render the synthesized memory outline (summaries + structure) with progressive disclosure",
319			Args:  cobra.NoArgs,
320			RunE: func(cmd *cobra.Command, args []string) error {
321				_, brainDir, _, err := resolveFactsTarget(cmd.Context(), opts, agentSurfaceTarget(opts, nil), "")
322				if err != nil {
323					return err
324				}
325				// Always rebuild the structure from the live facts (it is deterministic
326				// and never stale), then overlay stored summaries only where the node's
327				// fingerprint still matches — so a summary for a changed subtree is
328				// hidden rather than shown stale, and no `facts outline` run is required
329				// to see the map.
330				facts, err := factstore.Load(brainDir)
331				if err != nil {
332					return err
333				}
334				outline := buildFactOutlineTree(facts, opts.Now().UTC())
335				if stored, storedErr := loadFactOutline(brainDir); storedErr == nil {
336					for key, n := range outline.Nodes {
337						if s, ok := stored.Nodes[key]; ok && s.Fingerprint == n.Fingerprint && s.Summary != "" {
338							n.Summary = s.Summary
339							outline.Nodes[key] = n
340						}
341					}
342				}
343				node := path
344				if _, ok := outline.Nodes[node]; !ok {
345					return fmt.Errorf("no outline node %q", path)
346				}
347				// The outline counts what factstore.Load produced. When the manifest
348				// declares more than that, "root (4 facts)" is a count of survivors
349				// rendered as if it were the corpus. Qualify it before rendering,
350				// and exit nonzero so a caller cannot read the map as complete.
351				integrityErr := reportFactStoreIntegrity(cmd, brainDir, jsonOut)
352				if jsonOut {
353					if err := cmdutil.WriteJSON(cmd, outline); err != nil {
354						return err
355					}
356					return integrityErr
357				}
358				var b strings.Builder
359				renderFactOutline(&b, outline, node, depth)
360				if b.Len() == 0 {
361					fmt.Fprintln(cmd.OutOrStdout(), "no memories")
362					return integrityErr
363				}
364				fmt.Fprint(cmd.OutOrStdout(), b.String())
365				return integrityErr
366			},
367		}
368		cmd.Flags().StringVar(&path, "path", "", "Drill into a node key (a directory tier, e.g. internal/cli)")
369		cmd.Flags().IntVar(&depth, "depth", 0, "Levels to render below the node (0 = all)")
370		cmd.Flags().BoolVar(&jsonOut, "json", false, "Emit the outline as JSON")
371		return cmd
372	}
373	
374	// runFactsGC prunes over the flat store. branch is an explicit metadata
375	// filter: when set, only records stamped with that branch are gc candidates
376	// and everything else passes through untouched; empty means the whole store.
377	func runFactsGC(cmd *cobra.Command, opts Options, brainDir, branch string, force bool, retain time.Duration, jsonOut bool) error {
378		now := opts.Now().UTC()
379		gcPass := func(facts []factRecord) ([]factRecord, gcResult, error) {
380			taxonomy, err := factstore.LoadTaxonomy(brainDir, now)
381			if err != nil {
382				return nil, gcResult{}, err
383			}
384			scoped := facts
385			var passthrough []factRecord
386			if branch != "" {
387				scoped = scoped[:0:0]
388				for _, f := range facts {
389					if f.Branch == branch {
390						scoped = append(scoped, f)
391					} else {
392						passthrough = append(passthrough, f)
393					}
394				}
395			}
396			result := gcFacts(scoped, taxonomy, now, retain)
397			return append(passthrough, result.Kept...), result, nil
398		}
399		facts, err := factstore.Load(brainDir)
400		if err != nil {
401			return err
402		}
403		_, result, err := gcPass(facts)
404		if err != nil {
405			return err
406		}
407		summary := map[string]any{
408			"branch":    branch,
409			"pruned":    len(result.Pruned),
410			"orphans":   len(result.Orphans),
411			"remaining": len(result.Kept),
412			"applied":   force,
413		}
414		if force {
415			if err := brainstore.WithBrainWriteLockContext(cmd.Context(), brainDir, func() error {
416				if _, err := migrateFactStoreLocked(brainDir); err != nil {
417					return err
418				}
419				facts, err := factstore.Load(brainDir)
420				if err != nil {
421					return err
422				}
423				kept, res, err := gcPass(facts)
424				if err != nil {
425					return err
426				}
427				result = res
428				summary["pruned"] = len(result.Pruned)
429				summary["orphans"] = len(result.Orphans)
430				summary["remaining"] = len(result.Kept)
431				if err := factstore.Write(brainDir, kept); err != nil {
432					return err
433				}
434				return updateFactSourceManifestLocked(brainDir, now)
435			}); err != nil {
436				return err
437			}
438		}
439		if jsonOut {
440			return cmdutil.WriteJSON(cmd, summary)
441		}
442		verb := "would prune"
443		if force {
444			verb = "pruned"
445		}
446		scope := "in this repository"
447		if branch != "" {
448			scope = "stamped " + branch
449		}
450		fmt.Fprintf(cmd.OutOrStdout(), "%s %d memory(ies) %s (%d retracted/old-superseded); %d taxonomy-orphaned memory(ies) reported (kept); %d remaining\n",
451			verb, len(result.Pruned), scope, len(result.Pruned), len(result.Orphans), len(result.Kept))
452		if !force && len(result.Pruned) > 0 {
453			fmt.Fprintln(cmd.OutOrStdout(), "re-run with --force to apply")
454		}
455		return nil
456	}
