	sum := sha256.Sum256(data)
	return "sha256:" + hex.EncodeToString(sum[:])
}

func evalBrainManifestSHA256(brainDir string) string {
	return fileSHA256Hex(filepath.Join(brainDir, bmanifest.FileName))
}

