149	// TestDocumentedCommandsAreDiscoverable closes the gap between what the docs
150	// tell a reader to run and what `--help` will admit exists.
151	//
152	// `doctor` and `config` were both hidden. Meanwhile scripts/install.sh runs
153	// `entire brain config init`, runs `entire brain doctor`, and closes by telling
154	// the reader "re-run checks: entire brain doctor"; the README documents doctor's
155	// exit-code contract in its own section. A user who follows that advice once and
156	// later greps `--help` finds nothing, and concludes the command was removed.
157	//
158	// Every command named in a fenced block or inline code span of README.md,
159	// docs/getting-started.md, docs/operations.md or scripts/install.sh must appear
160	// in `--help`. Hiding one again is fine -- but then it has to stop being
161	// advertised, and this test says which document to edit.
162	func TestDocumentedCommandsAreDiscoverable(t *testing.T) {
163		root := NewRootCommand(Options{Version: "test"})
164	
165		// Only the surfaces a new user is actually pointed at. Design documents and
166		// plans describe futures, not the installed binary.
167		sources := []string{
168			"../../README.md",
169			"../../docs/getting-started.md",
170			"../../docs/operations.md",
171			"../../scripts/install.sh",
172		}
173	
174		// `entire brain <verb>` is the spelling every one of these documents uses,
175		// because all four describe the plugin install.
176		mention := regexp.MustCompile(`entire brain ([a-z][a-z-]*)`)
177	
178		visible := map[string]bool{}
179		for _, c := range root.Commands() {
180			if c.Hidden {
181				continue
182			}
183			visible[c.Name()] = true
184			for _, alias := range c.Aliases {
185				visible[alias] = true
186			}
187		}
188	
189		// Deliberately hidden AND deliberately documented. Each is a developer or
190		// machine surface whose reason for hiding is recorded at its registration
191		// in root.go and still holds; the documents that name them address that
192		// audience, not a new user. Adding to this list is how a decision to keep
193		// something hidden gets written down -- a new hidden-but-documented command
194		// fails this test until somebody does.
195		hiddenOnPurpose := map[string]string{
196			"review":           "machine contract for the host CLI's `entire review`, not a human verb",
197			"history-eval":     "measurement harness for the retrieval layer; developer tooling",
198			"history-eval-gen": "measurement harness for the retrieval layer; developer tooling",
199			"bench":            "maintainer-only measurement harness, explicitly introduced as such in getting-started",
200		}
201	
202		seen := map[string]string{}
203		for _, source := range sources {
204			data, err := os.ReadFile(source)
205			if err != nil {
206				t.Fatalf("read %s: %v", source, err)
207			}
208			for _, match := range mention.FindAllStringSubmatch(string(data), -1) {
209				verb := match[1]
210				if _, ok := seen[verb]; !ok {
211					seen[verb] = source
212				}
213			}
214		}
215		if len(seen) == 0 {
216			t.Fatal("no documented commands found -- the test is checking nothing")
217		}
218	
219		for verb, source := range seen {
220			// A word that is not a command at all is a prose false positive
221			// ("entire brain from scratch"), not a discoverability failure.
222			if cmd, _, err := root.Find([]string{verb}); err != nil || cmd == root {
223				continue
224			}
225			if visible[verb] {
226				if reason, ok := hiddenOnPurpose[verb]; ok {
227					t.Errorf("`%s` is visible in --help but still listed as hidden on purpose (%s): drop it from hiddenOnPurpose", verb, reason)
228				}
229				continue
230			}
231			if _, ok := hiddenOnPurpose[verb]; ok {
232				continue
233			}
234			t.Errorf("%s tells the reader to run `entire brain %s`, but it is hidden from --help: unhide it, or stop advertising it", source, verb)
235		}
236	}
237	
238	// --- the other direction -----------------------------------------------------
239	
240	// userFacingDocs are the pages a new user is pointed at, and the ones both
241	// directions of the discoverability contract are checked against.
242	// scripts/install.sh is deliberately absent: it is a script that happens to run
243	// some commands, not a document anybody reads to learn the surface.
244	var userFacingDocs = []string{
